 h=W/f'P100-{c:03}';p=h/'package';spec=json.loads((h/'SPEC.json').read_text());r=json.loads((p/'rules.json').read_text());receipt=json.loads((h/'CONFIRMATION.json').read_text());b=json.loads((h/'BASELINES.json').read_text());a=[json.loads(f.read_text()) for f in sorted(h.glob('attempts/attempt-*/metrics.json'))];sel=r['reference_selected_model'];m=r['models']['reference'];dev=b[sel]['metrics']['primary_error'] if sel in b else next(v['primary_error'] for v in a if v['model_name']==sel);met=receipt['metrics'];z=DETAIL[c];unit='probability squared' if c==89 else spec['unit'];bm={k:v['primary_error'] for k,v in met.items() if k.startswith('baseline_')};bestbase=min(bm.values());cl='validated_extension' if c in [32,34,89] and met['reference']['primary_error']<min(v for k,v in bm.items() if k!=sel)*.99 else 'reproduction';adm='supported' if c in [32,34,89] and cl=='validated_extension' else 'partially_supported';f1=dict(finding_id=f'P100-{c:03}-F01',classification=cl,admission=adm,claim=z['meaning'],equation=m['equation'],model_id='reference',task_id=f'P100-{c:03}.original.v1',evidence=dict(development_primary_error=dev,confirmation_primary_error=met['reference']['primary_error'],confirmation_groups=len(receipt['groups']),confirmation_rows=receipt['rows'],unit=unit,metrics='evidence/metrics.csv',group_metrics='evidence/by_group.csv',predictions='evidence/predictions.csv.gz',state='rules.json'),falsification='Compare every eligible held-out group to all frozen simple/domain/flexible controls; later diagnostic winners are never substituted for the preselected reference.',known_prior_art=z['prior'],scope=z['limits'])
 f2=dict(finding_id=f'P100-{c:03}-F02',classification='informative_falsification',admission='supported',claim=z['negative'],equation=None,evidence=dict(attempts=len(a),best_attempt_development_error=min(v['primary_error'] for v in a),development_selected_error=dev,development_diagnostics='research_history/DEVELOPMENT_DIAGNOSTICS.json'),known_prior_art=z['prior'],falsification='Supported negative evidence concerns only the enumerated candidates and protocol; it does not disprove domain biology or physics.',scope=z['limits'],underlying_proposal_disposition='Several proposed mechanisms are unsupported; this negative finding and the tested models have distinct dispositions.')
 findings=[f1,f2]
 if c==34:
  findings.append(dict(finding_id='P100-034-F03',classification='validated_extension',admission='partially_supported',claim='Low-dose calibration enables a compact finite-response-reserve description; genotype-specific terms must justify improvement beyond those measurements.',equation=m['equation'],evidence=dict(attempts='attempts004–010',selected_model=sel),known_prior_art=z['prior'],falsification='Requires paired evidence against both earlier-calibration ablation and genotype-rate expansion; source dose order remains confounded with time.',scope=z['limits']))
 write(p/'findings.json',dict(case_id=f'P100-{c:03}',findings=findings,reference_disposition='Frozen development-selected reference; candidate laws and negative findings require separate scientific review.',review_pending='Independent computational and scientific-critical review by different agents'))
 (p/'scientific_checks.py').write_text(checks)
 coeff='\n'.join(f'| {i} | {v:.12g} |' for i,v in enumerate(m['coef']));eq='# Executable equations\n\nThe exact frozen coefficients and feature transformations are in `rules.json` and `run.py`. No coefficient is fitted during replay.\n\nSelected equation: '+m['equation']+'\n\n| Coefficient index | Value |\n|---|---:|\n'+coeff+'\n\nEach model is separate from the scientific finding and evaluation task. All alternative states remain available for numerical comparison.\n'
 if c==32:eq+='\nFor the selected flexible model, the ordered feature vector is: 1, p0,p05,p10,p20,p30,p40,p50,di0,de0,di20,de20,p0*FEM,p0*BH. The predicted pressure is the dot product with the coefficient vector. All pressures are cmH2O; suffixes are lag in centiseconds.\n'
 if c==89:eq+='\nFor the selected flexible model let r=reward/2, p=probability, a=child, m=multi, v=description, h=history_mean-0.5, l=lag_choice-0.5. Its ordered vector is [1,r,p,r*p,r^2,p^2,a,m,v,a*m,a*v,r*a,p*a,r*m,p*m,r*v,p*v,h,l,h*a,h*m,trial_progress]. Predicted probability is sigmoid(beta dot vector). Coefficients are dimensionless.\n'
 if c==34:eq+='\nLet u=I(0.4mM), v=I(0.75mM), d=C-0.75mM. The conserved reserve reference is I_hat=v+max(A+B*u-v,0)*d/(K+d), when selected. A is nA, B dimensionless and K mM. Numerical values are the frozen coefficient vector in this order. Other selected forms are identified explicitly above.\n'
 (p/'EQUATIONS.md').write_text(eq)
 table='| Frozen model | Confirmation primary error |\n|---|---:|\n'+'\n'.join(f'| {k} | {v["primary_error"]:.8g} |' for k,v in met.items() if k=='reference' or k.startswith('baseline'))
 perf=f'The reference `{sel}` was chosen before confirmation. Development error was **{dev:.8g}**; reserved-group error is **{met["reference"]["primary_error"]:.8g} {unit}** across **{len(receipt["groups"])} groups and {receipt["rows"]} observations**. Scores use equal group weights, with equal row weights within each group. No population confidence interval is inferred from these small samples.'
 if c==89:perf+=' Brier score is the mean squared probability error; lower is better. Supplementary threshold statistics are row-count diagnostics, while Brier and log loss are group balanced.'
 report='# '+z['title']+'\n\n'+z['intro']+'\n\n## Question and information budget\n\n'+spec['timing']+' '+spec['calibration']+'\n\n## Findings and interpretation\n\n'+z['meaning']+'\n\nThe selected executable relation is:\n\n`'+m['equation']+'`\n\nThe full coefficient table and variable ordering are in `EQUATIONS.md`; `rules.json` contains exact precision. All equation inputs and their units are declared in `task_spec.json`.\n\n'+z['negative']+'\n\n## Experimental design and performance\n\n'+perf+'\n\n'+table+'\n\n'+str(len(a))+' substantive development attempts were preserved. Selection used whole-group out-of-fold errors and preferred the simplest model within1% of the minimum. Continuation ended only after two consecutive substantive attempts failed to improve prediction and no supported mechanism/robustness gain justified another candidate. Confirmation ran separately after code, source, states, selection and stopping were frozen. No later diagnostic winner was promoted.\n\n## Scope, prior work and value\n\n'+z['limits']+'\n\n'+z['prior']+'\n\nNo new universal law, independent experimental replication, clinical benefit or demonstrated industrial impact is claimed. Alternative valid discoveries can be evaluated using the same task contract; exact agreement with this equation is unnecessary. Negative findings describe failed tested hypotheses, not a lack of scientific phenomena.\n\n## Reproduction and evaluation\n\nRun `python run.py` inside this folder to verify frozen asset hashes and reproduce all saved predictions. It uses no network, fitting, research-history import or hidden model state. Submitter predictions must use the same sample IDs, units, information budget and group cohort. `scientific_checks.py` adds domain diagnostics to the shared benchmark scorer; it does not execute submitted code. New endpoints require a separately reviewed task.\n\nSources: [authoritative data]('+spec['source']+'), [primary study]('+spec['paper']+'). Source assets are CC BY4.0; citations and exact native hashes are retained in the scenario research layer. Current confirmation outcomes are exposed for all future users.\n'
 (p/'FINDINGS.md').write_text(report)
 (p/'README.md').write_text('# P100-'+f'{c:03}'+' final results\n\nStart with `FINDINGS.md` (editable human introduction), then `EQUATIONS.md`, `findings.json` and `task_spec.json`. `rules.json` and `run.py` reproduce the executable references. `data/` contains the declared confirmation inputs and observations; `evidence/` contains predictions and group-wise scores. Historical hypotheses, diagnostics and negative attempts live outside this final package.\n\nThis is a source-aware reference portfolio, not certified ground truth or proven novelty.\n')
 (p/'EVALUATOR.md').write_text('# Evaluation contract\n\nPrimary metric: '+spec['kind']+' with equal independent-group weights; units '+unit+'. Each prediction must be finite and align exactly to every declared sample identity; missing predictions require explicit coverage/abstention treatment in the shared scorer. Alternative equations receive the same tests and need not match our model.\n\nInputs and calibration: '+spec['calibration']+'\n\nTiming: '+spec['timing']+'\n\nRegistered primary task, group definitions and exposure are in `task_spec.json`. Check source hashes before preparation. Local trusted reference replay uses `python run.py`; arbitrary prediction-file scoring does not execute submitted code. Intervals, event thresholds and proposed new endpoints must declare meanings and uncertainty assumptions; never derive acceptance tolerances from a comparator error.\n\nNo aggregate scientific-discovery score is implied by lower prediction error. Scientific review separately assesses mechanism, novelty, applicability and negative evidence.\n')
 write(p/'DEPENDENCIES.json',dict(python=platform.python_version(),numpy=np.__version__,pandas=pd.__version__,scipy=__import__('scipy').__version__,execution='read-only frozen state prediction; no fitting or network'))
 summary='# P100-'+f'{c:03}'+' campaign summary\n\n'+perf+'\n\n| Attempt | Hypothesis/model | Development error | Parameters | Improvement over incumbent>1% |\n|---|---|---:|---:|---|\n'+'\n'.join(f'| {i+1:03} | {v["model_name"]} | {v["primary_error"]:.8g} | {v["parameter_count"]} | {v["prediction_gain"]} |' for i,v in enumerate(a))+'\n\n'+table+'\n\nUseful scientific failures are preserved in `attempts/`. No unfavorable attempt is deleted. See `DEVELOPMENT_DIAGNOSTICS.json`, source/split/protocol freezes, first `CONFIRMATION.json`, and final reader.\n'
 (h/'SUMMARY.md').write_text(summary);(h/'LESSONS.md').write_text('# Lessons for later ASD\n\n'+z['lesson']+'\n\n'+z['limits']+'\n\nFuture revisions must label this confirmation cohort exposed and obtain new evidence before using fresh-confirmation language. Preserve scientific failures; do not relabel a later comparator winner as the original selected model.\n');(h/'PRIOR_ART_REVIEW.md').write_text('# Prior-art and novelty assessment\n\n'+z['prior']+'\n\nPrimary sources read during this campaign: '+spec['source']+' and '+spec['paper']+'. Source methods and known conclusions informed hypotheses before selection. Targeted title/domain searches were performed on2026-10-01. Search records in `PRIOR_ART.json` identify the primary URLs. This limited targeted review does not establish exhaustive novelty.\n');write(p/'MANIFEST.json',dict(assets=[dict(path=str(f.relative_to(p)),bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()) for f in sorted(p.rglob('*')) if f.is_file() and f.name!='MANIFEST.json' and '__pycache__' not in f.parts]));print('Finished',c,'finding',cl,adm)
